static const z_t6083_t _zag1634 = { { .data = "win_error_text", .size = 14 }, { .length = 1, .data = _zag1633 }, { .length = 1, .data = _zag1605 }, { .data = "/* FormatMessageW's text for a Win32 error, as UTF-8 without the trailing line\n   break; NULL when the system has none */\nstatic char* z_win_error_text(DWORD code) {\n    wchar_t* w = NULL;\n    DWORD n = FormatMessageW(\n        FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,\n        NULL, code, 0, (LPWSTR)&w, 0, NULL\n    );\n    if (n == 0 || w == NULL) return NULL;\n    while (n > 0 && (w[n - 1] == L'\\r' || w[n - 1] == L'\\n' || w[n - 1] == L' ')) n--;\n    char* s = z_win_utf8(w, (int)n, NULL);\n    LocalFree(w);\n    return s;\n}", .size = 575 } };
